def celsius_to_fahrenheit(celsius):
    return (celsius * 9 / 5) + 32

while True:
    user_input = input('Enter temperature in Celsius (or quit): ')
    if user_input == 'quit':
        break
    try:
        celsius = float(user_input)
        fahrenheit = celsius_to_fahrenheit(celsius)
        print('Fahrenheit:', fahrenheit)
    except ValueError:
        print('Invalid input. Please enter a number or quit.')

days_late = int(input('Enter days the book is late: '))
if days_late <= 0:
    print('No fine.')
elif days_late <= 5:
    fine = days_late * 0.50
    print('Fine:', fine)
else:
    fine = 5 * 0.50 + (days_late - 5) * 1.00
    print('Fine:', fine)

def is_leap_year(year):
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    if year % 4 == 0:
        return True
    return False

user_input = input('Enter a year: ')
try:
    year = int(user_input)
    if year <= 0:
        print('Year must be a positive integer.')
    else:
        if is_leap_year(year):
            print(year + ' is a leap year.')
        else:
            print(year + ' is not a leap year.')
except ValueError:
    print('Invalid input. Please enter a valid integer.')
